// Max entries to return with full parameter/example detail.
// Prevents multi-thousand-token responses that blow up context windows.
const MAX_FULL_DETAIL = 5;
export function searchRegistry(query, category, detailLevel = 'description') {
    const lowerQuery = query.toLowerCase().trim();
    // Exact method name match — return just that entry (always full detail)
    // Handles "figma.createFrame", "createFrame", etc.
    const exactMatch = registry.find((entry) => {
        const name = entry.name.toLowerCase();
        return name === lowerQuery || name === `figma.${lowerQuery}`;
    });
    if (exactMatch && (!category || exactMatch.category === category)) {
        return [exactMatch];
    }
    // Split query into words and score each entry by how many words match (ranked OR).
    // An entry matches if ANY word matches name or description.
    const words = lowerQuery.split(/\s+/).filter(Boolean);
    const scored = [];
    for (const entry of registry) {
        if (category && entry.category !== category)
            continue;
        const name = entry.name.toLowerCase();
        const desc = entry.description.toLowerCase();
        let score = 0;
        for (const w of words) {
            if (name.includes(w))
                score += 3; // name match is stronger
            else if (desc.includes(w))
                score += 1;
        }
        if (words.length === 0 || score > 0) {
            scored.push({ entry, score });
        }
    }
    // Sort by score descending, then alphabetically
    scored.sort((a, b) => b.score - a.score || a.entry.name.localeCompare(b.entry.name));
    switch (detailLevel) {
        case 'name':
            return scored.map((s) => ({
                name: s.entry.name,
                category: s.entry.category,
            }));
        case 'description':
            return scored.map((s) => ({
                name: s.entry.name,
                category: s.entry.category,
                description: s.entry.description,
            }));
        case 'full': {
            // Return top N with full detail; show remaining as names only
            const topN = scored.slice(0, MAX_FULL_DETAIL).map((s) => s.entry);
            const overflow = scored.slice(MAX_FULL_DETAIL);
            if (overflow.length === 0)
                return topN;
            return {
                results: topN,
                alsoMatched: overflow.map((s) => s.entry.name),
                hint: `${overflow.length} more matched. Use an exact method name (e.g. query: "figma.createFrame") for full details on a specific method.`,
            };
        }
    }
}
